    {
      "term": "فيه",
      "category": "Particle",
      "definition": "Says something exists: there is, there are. With a question tone, it asks if something is around.",
      "example": "فيه صيدلية قريبة من هنا؟ — Is there a pharmacy near here?",
      "discussion": "The negative is one word, مفيش: مفيش عيش, there's no bread. You'll hear it all day."
    },
    {
      "term": "عايز",
      "category": "Modal",
      "definition": "Wants something, or wants to do something. A noun or a present verb comes right after.",
      "example": "أنا عايز اتنين شاي، لو سمحت. — Two teas, please.",
      "discussion": "It agrees with the speaker like an adjective: a woman says عايزة, a group says عايزين."
    },
    {
      "term": "بـ + مضارع",
      "category": "Pattern",
      "definition": "Marks habits and actions happening now. Add بـ to the present verb: بشتغل, I work or I'm working.",
      "example": "إنت بتشتغل فين دلوقتي؟ — Where are you working these days?",
      "anti_example": "Not أنا أشرب قهوة كل يوم: without بـ it sounds unfinished. Say بشرب قهوة كل يوم."
    },
    {
      "term": "مش",
      "category": "Particle",
      "definition": "Negates words that aren't verbs, like adjectives, nouns and عايز. The future with حـ takes it too.",
      "example": "لا، شكرًا يا طنط، أنا مش جعان. — No thanks, auntie, I'm not hungry.",
      "anti_example": "Not مش شربت for 'I didn't drink': a past verb takes ما…ش, so مشربتش."
    },
    {
      "term": "لازم",
      "category": "Modal",
      "definition": "Obligation: must, have to. It never changes, whoever you're talking about.",
      "example": "لازم أمشي دلوقتي، الساعة اتناشر. — I have to go, it's midnight.",
      "anti_example": "Not مش لازم for 'you mustn't': that means 'you don't have to'. For 'mustn't', say ماينفعش."
    },
    {
      "term": "عند + ضمير",
      "category": "Pattern",
      "definition": "Your 'have' in Egyptian: عند plus an ending for the owner, as in عندي, عندك, عنده.",
      "example": "عندك شاحن؟ الموبايل فصل. — Got a charger? My phone died.",
      "anti_example": "Not مش عندي for 'I don't have': it takes ما…ش, so معنديش."
    },
    {
      "term": "ممكن",
      "category": "Modal",
      "definition": "Politely asks for something, or says it's possible: can I, could you, maybe.",
      "example": "ممكن الحساب، لو سمحت؟ — Can we have the bill, please?",
      "discussion": "On its own it answers 'maybe': جاي بكرة؟ ممكن. Starting a request with it already sounds polite."
    },
    {
      "term": "ما…ش",
      "category": "Pattern",
      "definition": "Wraps a verb to negate it: ما before, ش after, as in مفهمتش, I didn't understand.",
      "example": "أنا مبحبش القهوة من غير سكر. — I don't like coffee without sugar.",
      "discussion": "People usually write ما as just م stuck to the verb: مبحبش. The future still takes مش: مش حروح."
    },
    {
      "term": "يقدر",
      "category": "Modal",
      "definition": "Talks about real ability: can, be able to. It changes with the person: أقدر, تقدر, يقدر.",
      "example": "مقدرش آجي النهارده، أنا تعبان. — I can't come today, I'm sick.",
      "discussion": "For asking a favour, Egyptians usually start with ممكن instead. يقدر is more about whether you really can."
    },
    {
      "term": "حـ + مضارع",
      "category": "Pattern",
      "definition": "Puts a verb in the future: add حـ to the present verb, as in حسافر, I'll travel.",
      "example": "حنروح إسكندرية يوم الخميس. — We're going to Alexandria on Thursday.",
      "discussion": "Many people write it هـ instead: هسافر. Read both spellings as the same thing."
    }
